import java.util.*;

class Solution {
    public int[] sortDescending(int[] nums) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> Integer.compare(b, a));
        for (int x : nums) maxHeap.offer(x);
        int[] res = new int[nums.length];
        for (int i = 0; i < res.length; i++) {
            res[i] = maxHeap.poll();
        }
        return res;
    }
}

