import java.util.*;

class Solution {
    public int[] mergeKSorted(int[][] lists) {
        int total = 0;
        for (int[] list : lists) total += list.length;
        int[] out = new int[total];
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        for (int i = 0; i < lists.length; i++) {
            if (lists[i].length > 0) heap.offer(new int[]{lists[i][0], i, 0});
        }
        int pos = 0;
        while (!heap.isEmpty()) {
            int[] top = heap.poll();
            out[pos++] = top[0];
            int li = top[1], next = top[2] + 1;
            if (next < lists[li].length) heap.offer(new int[]{lists[li][next], li, next});
        }
        return out;
    }
}
